const AI_GROUP = "Ai+";
const AI_STABLE_GROUP = "Ai稳定选择";
const AI_AUTO_GROUP = "Ai测速备用";
const LEGACY_AI_AUTO_GROUP = "Ai自动选择";
const SCHOLAR_GROUP = "学术搜索";
const ACADEMIC_GROUP = "学术访问";
const FALLBACK_GROUP = "漏网之鱼";

// Health probe for Ai测速备用. The primary checks the ChatGPT trace endpoint's
// current HTTP response, not login, region permissions or complete service
// availability. If that endpoint becomes unavailable, switch AI_PROBE_URL
// to the backup below, which only checks generic connectivity. Confirm an
// endpoint is reachable before changing any probe URL.
const AI_PROBE_URL = "https://chatgpt.com/cdn-cgi/trace";
const AI_PROBE_URL_BACKUP = "https://www.gstatic.com/generate_204";

// AI node selection is a positive whitelist: only US nodes enter the AI pool,
// because OpenAI and Anthropic geo-block most other regions. To widen the
// region set later (for example US + Japan), extend AI_INCLUDE_SOURCE — do
// NOT revert to an exclusion-style filter. Both observed naming styles must
// keep matching:
//   🇺🇸 美国-BGP-05【优化】
//   🇺🇸 Basic-美国-BGP-01|v202605
// The bounded us/usa tokens keep names like "Russia" or "Australia" from
// matching accidentally, "america" covers English-only US naming such as
// "America-Los Angeles", and u.s.a. covers the dotted spelling.
const AI_INCLUDE_SOURCE = "(?:🇺🇸|美国|美國|america|united[ -]?states|u\\.s\\.a\\.?|(?:^|[^a-z])(?:us|usa)(?:[^a-z]|$))";
// AI_EXCLUDE only strips informational nodes injected by airports. Region
// filtering is AI_INCLUDE's job; a US-named node stays even if its name also
// contains region words such as 香港. Observed variants across airports:
//   剩余流量: 876.18 GB
//   距离下次重置剩余：24 天
//   套餐到期：2027-10-08
//   官网 xxx.invalid 群组 t.me/...
//   【官网】xxx.invalid     (bracket right after 官网)
//   Expire20270818         (no separator at all)
//
// 到期/过期/重置 match as whole phrases or when a year follows. A bare "到期"
// would also hit marketing-style node names such as "香港 永不过期 01", which
// are real nodes and must stay selectable. The core evaluates this filter with
// Go RE2, so lookbehind/lookahead are not available.
const AI_EXCLUDE_SOURCE = "(?:🇺🇳|剩余流量|流量剩余|距离下次重置|重置剩余|到期时间|过期时间|套餐到期|套餐提示|订阅信息|(?:^|[\\s|_\\-【】()（）])(?:expire|traffic|sync|reset|官网|套餐|订阅|更新|客服|网址)(?:[\\s:：|_\\-\\d【】()（）]|$)|(?:到期|过期|重置)[:：\\s_|-]*\\d{4}|剩余[:：\\s_|-]*\\d)";

const AI_INCLUDE = new RegExp(AI_INCLUDE_SOURCE, "i");
const AI_EXCLUDE = new RegExp(AI_EXCLUDE_SOURCE, "i");

// Mihomo (Go RE2) group filters have no /i flag; an inline (?i) group is
// required for the runtime filter written onto provider-mode groups.
const coreFilter = (source) => `(?i)${source}`;

// Built-in non-proxy node types that must never join an AI group.
const NON_PROXY_TYPES = new Set([
  "direct",
  "reject",
  "reject-drop",
  "pass",
  "pass-name",
  "compatible",
  "dns-out",
  "dns-in",
]);

function groupByName(config, name) {
  const groups = Array.isArray(config["proxy-groups"]) ? config["proxy-groups"] : [];
  return groups.find((group) => group && group.name === name);
}

function providerNames(config) {
  const providers = config["proxy-providers"];
  if (!providers || typeof providers !== "object" || Array.isArray(providers)) return [];
  return Object.keys(providers).filter((name) => typeof name === "string" && name);
}

function eligibleAiNodes(config) {
  if (!Array.isArray(config.proxies)) return [];
  const seen = new Set();
  return config.proxies
    .filter((proxy) => proxy && typeof proxy.name === "string" && proxy.name)
    .filter((proxy) => !NON_PROXY_TYPES.has(String(proxy.type || "").toLowerCase()))
    .map((proxy) => proxy.name)
    // Whitelist first: a node named like a US node stays even if its name
    // also contains region words (protects against airport rename mixups).
    .filter((name) => AI_INCLUDE.test(name) && !AI_EXCLUDE.test(name))
    .filter((name) => {
      if (seen.has(name)) return false;
      seen.add(name);
      return true;
    });
}

// Subscription-specific fix: some providers ship Apple and AppleDev
// rule-providers that share one cache path, which breaks Mihomo startup.
// This is a targeted correction for that particular subscription —
// re-evaluate it whenever the subscription changes.
function fixProviderPaths(config) {
  const providers = config["rule-providers"];
  if (!providers || typeof providers !== "object") return;
  const apple = providers.Apple;
  const appleDev = providers.AppleDev;
  if (apple && appleDev && apple.path && apple.path === appleDev.path) {
    apple.path = "./providers/rule/Apple.yaml";
  }
}

// A group name can be referenced from another group's member list or from a
// rule. Deleting a referenced group would leave a dangling target, and mihomo
// then refuses the whole subscription - worse than not overriding at all.
function isGroupReferenced(config, name) {
  for (const group of Array.isArray(config["proxy-groups"]) ? config["proxy-groups"] : []) {
    if (!group || group.name === name) continue;
    if (Array.isArray(group.proxies) && group.proxies.includes(name)) return true;
    if (Array.isArray(group.use) && group.use.includes(name)) return true;
  }
  for (const rule of Array.isArray(config.rules) ? config.rules : []) {
    if (typeof rule !== "string") continue;
    if (ruleTarget(rule) === name) return true;
  }
  return false;
}

// Remove groups owned by this project so re-running the script stays
// idempotent. The four groups below are rebuilt immediately, so dropping them
// is always safe. Ai自动选择 is NOT rebuilt: keep it whenever anything still
// references it, because deleting a referenced group leaves a dangling target
// and mihomo then refuses the whole subscription.
function removeGeneratedGroups(config) {
  const removable = new Set([
    AI_STABLE_GROUP,
    AI_AUTO_GROUP,
    SCHOLAR_GROUP,
    ACADEMIC_GROUP,
  ]);
  if (!isGroupReferenced(config, LEGACY_AI_AUTO_GROUP)) {
    removable.add(LEGACY_AI_AUTO_GROUP);
  }
  config["proxy-groups"] = config["proxy-groups"].filter(
    (group) => group && !removable.has(group.name),
  );
}

function insertGroupsBeforeAi(config, groups) {
  const aiIndex = config["proxy-groups"].findIndex(
    (group) => group && group.name === AI_GROUP,
  );
  config["proxy-groups"].splice(aiIndex, 0, ...groups);
}

// Build the AI/Scholar/Academic group set. Inline subscriptions get an
// explicit node list; proxy-providers subscriptions get use+filter and the
// core resolves the same nodes at runtime. Both produce an identical group
// shape, so switching airports changes only the node source, not the policy.
function configureAiGroups(config, ai, source) {
  const aiStable = {
    name: AI_STABLE_GROUP,
    type: "select",
  };
  const aiAuto = {
    name: AI_AUTO_GROUP,
    type: "url-test",
    url: AI_PROBE_URL,
    interval: 300,
    tolerance: 50,
    lazy: true,
    timeout: 8000,
    "max-failed-times": 2,
    "expected-status": 200,
  };
  if (source.nodes) {
    aiStable.proxies = [...source.nodes];
    aiAuto.proxies = [...source.nodes];
  } else {
    // provider mode: mihomo fills these in from the provider at runtime and
    // the user can still pick a node manually in Ai稳定选择.
    const includeFilter = coreFilter(AI_INCLUDE_SOURCE);
    const excludeFilter = coreFilter(AI_EXCLUDE_SOURCE);
    for (const group of [aiStable, aiAuto]) {
      group.use = [...source.providers];
      group.filter = includeFilter;
      group["exclude-filter"] = excludeFilter;
    }
  }
  const scholar = {
    name: SCHOLAR_GROUP,
    type: "select",
    proxies: [AI_STABLE_GROUP, AI_AUTO_GROUP],
  };
  const academic = {
    name: ACADEMIC_GROUP,
    type: "select",
    proxies: ["DIRECT", AI_GROUP],
  };
  insertGroupsBeforeAi(config, [aiStable, aiAuto, scholar, academic]);

  // Explicit member lists avoid runtime compatibility problems in FlClash
  // versions that display newer dynamic fields but do not preserve them.
  // Coerce the type to select: the generated Ai+ only references other groups,
  // and select is the group type guaranteed to accept group members, whatever
  // type the new airport happened to ship.
  // `use` must go as well: mihomo merges provider members into a group, so a
  // leftover `use` without its filter would add unfiltered (non-US and
  // informational) nodes straight into Ai+.
  ai.type = "select";
  ai.proxies = [AI_STABLE_GROUP, AI_AUTO_GROUP];
  for (const key of [
    "include-all",
    "include-all-proxies",
    "include-all-providers",
    "use",
    "filter",
    "exclude-filter",
    "exclude-type",
    "default-selected",
    "empty-fallback",
  ]) delete ai[key];
}

// Returns the applied mode:
//   "inline"  - US nodes enumerated from config.proxies
//   "provider"- nodes resolved at runtime from proxy-providers
//   "no-nodes"- no usable node source; no groups are built
//   "degraded"- the subscription has no proxy-groups array at all
// Everything degrades instead of throwing: rule injection never points at a
// policy target this subscription does not have (see configureRules), and a
// missing Ai+ group is created, so a different airport keeps working.
function configureGroups(config, warnings) {
  if (!Array.isArray(config["proxy-groups"])) {
    warnings.push("subscription has no proxy-groups array; group configuration skipped, rules still applied");
    return "degraded";
  }

  const nodes = eligibleAiNodes(config);
  const providers = providerNames(config);
  let mode;
  let source;
  if (nodes.length) {
    mode = "inline";
    source = { nodes };
  } else if (providers.length) {
    mode = "provider";
    source = { providers };
  } else {
    // No US-named node and no provider to resolve at runtime. Do not throw and
    // do not create groups: rules whose target does not exist are skipped, so
    // the direct/tailscale/ad-block parts still apply and the marker explains
    // what was dropped.
    warnings.push(
      "no usable AI node source (no US-named node and no proxy-providers); " +
      "AI, Scholar and Academic groups skipped",
    );
    return "no-nodes";
  }

  let ai = groupByName(config, AI_GROUP);
  if (!ai) {
    // A different airport may not ship an Ai+ group at all. Create it so the
    // AI/Scholar/Academic rules stay valid instead of being dropped. It is
    // placed before 漏网之鱼 when that group exists, otherwise at the end.
    ai = { name: AI_GROUP, type: "select", proxies: [] };
    const groups = config["proxy-groups"];
    const fallbackIndex = groups.findIndex(
      (group) => group && group.name === FALLBACK_GROUP,
    );
    groups.splice(fallbackIndex === -1 ? groups.length : fallbackIndex, 0, ai);
    warnings.push(`subscription had no ${AI_GROUP} group; created it`);
  }

  removeGeneratedGroups(config);
  configureAiGroups(config, ai, source);

  const fallback = groupByName(config, FALLBACK_GROUP);
  if (fallback) {
    const choices = Array.isArray(fallback.proxies) ? fallback.proxies : [];
    fallback.proxies = ["DIRECT", ...choices.filter((choice) => choice !== "DIRECT")];
    delete fallback["default-selected"];
  } else {
    warnings.push(`subscription is missing ${FALLBACK_GROUP}; fallback adjustment skipped`);
  }

  return mode;
}

function ruleTarget(rule) {
  if (typeof rule !== "string") return null;
  const parts = rule.split(",").map((part) => part.trim());
  if (parts[0] === "MATCH") return parts[1] || null;
  if (parts.length < 3) return null;
  return parts[2];
}

// Prepend the custom rules, skipping any whose policy target this
// subscription does not provide. A subscription from a different airport may
// lack Ai+ or 学术访问 entirely; injecting such a rule would make mihomo
// refuse the whole config, which is far worse than skipping that rule-set.
// Returns the rules that were actually injected.
function configureRules(config, warnings) {
  if (!Array.isArray(config.rules)) config.rules = [];

  const groupNames = new Set(
    (Array.isArray(config["proxy-groups"]) ? config["proxy-groups"] : [])
      .map((group) => group && group.name)
      .filter(Boolean),
  );
  const proxyNames = new Set(
    (Array.isArray(config.proxies) ? config.proxies : [])
      .map((proxy) => proxy && proxy.name)
      .filter(Boolean),
  );
  const builtinTargets = new Set(["DIRECT", "REJECT", "REJECT-DROP", "PASS", "COMPATIBLE"]);
  const allowed = (target) =>
    builtinTargets.has(target) || groupNames.has(target) || proxyNames.has(target);

  const retained = [];
  const skipped = new Set();
  for (const rule of CUSTOM_RULES) {
    const target = ruleTarget(rule);
    if (target && !allowed(target)) {
      skipped.add(target);
      continue;
    }
    retained.push(rule);
  }
  for (const target of skipped) {
    warnings.push(
      `subscription has no ${target} policy target; custom rules for it were skipped`,
    );
  }

  const custom = new Set(retained);
  const customRuleKey = (rule) => {
    if (typeof rule !== "string") return null;
    const parts = rule.split(",").map((part) => part.trim());
    if (parts.length < 2 || ![
      "DOMAIN",
      "DOMAIN-SUFFIX",
      "DOMAIN-KEYWORD",
      "DOMAIN-WILDCARD",
      "DOMAIN-REGEX",
      "IP-CIDR",
      "IP-CIDR6",
      "SRC-IP-CIDR",
      "DST-PORT",
      "SRC-PORT",
      "PROCESS-NAME",
      "PROCESS-PATH",
      "NETWORK",
      "GEOIP",
      "GEOSITE",
    ].includes(parts[0].toUpperCase())) return null;
    const key = parts.slice(0, 2);
    if (parts[parts.length - 1] === "no-resolve") key.push("no-resolve");
    return key.join(",");
  };
  const customKeys = new Set(retained.map(customRuleKey));
  const original = config.rules.filter(
    (rule) => typeof rule !== "string" || !(
      custom.has(rule) ||
      rule.startsWith("RULE-SET,Custom-") ||
      customKeys.has(customRuleKey(rule))
    ),
  );
  config.rules = [...retained, ...original];
  return retained;
}

// Groups this run failed to produce are reported through warnings instead of
// throwing, so a partial subscription never cancels the rule override.
// In degraded/no-nodes modes nothing was configured, so no group is validated.
function validateResult(config, mode, retainedRules) {
  if (mode === "inline" || mode === "provider") {
    const names = config["proxy-groups"].map((group) => group && group.name);
    if (names.some((name, index) => !name || names.indexOf(name) !== index)) {
      throw new Error("proxy group names must be present and unique");
    }

    for (const required of [
      AI_STABLE_GROUP,
      AI_AUTO_GROUP,
      AI_GROUP,
      SCHOLAR_GROUP,
      ACADEMIC_GROUP,
    ]) {
      if (!names.includes(required)) throw new Error(`generated group is missing: ${required}`);
    }
    const stable = groupByName(config, AI_STABLE_GROUP);
    const auto = groupByName(config, AI_AUTO_GROUP);
    if (mode === "inline") {
      if (!stable.proxies.length || !auto.proxies.length) {
        throw new Error("AI stable/backup group is empty");
      }
    } else if (!Array.isArray(stable.use) || !stable.use.length ||
               !Array.isArray(auto.use) || !auto.use.length) {
      throw new Error("AI stable/backup group does not resolve provider nodes");
    }

    const expectedAiChoices = [AI_STABLE_GROUP, AI_AUTO_GROUP];
    if (JSON.stringify(groupByName(config, AI_GROUP).proxies) !==
        JSON.stringify(expectedAiChoices)) {
      throw new Error("Ai+ does not prefer stable selection");
    }
    if (JSON.stringify(groupByName(config, SCHOLAR_GROUP).proxies) !==
        JSON.stringify(expectedAiChoices)) {
      throw new Error("academic search does not share the stable AI exit");
    }
    if (JSON.stringify(groupByName(config, ACADEMIC_GROUP).proxies) !==
        JSON.stringify(["DIRECT", AI_GROUP])) {
      throw new Error("academic access does not prefer DIRECT with Ai+ backup");
    }

    const fallback = groupByName(config, FALLBACK_GROUP);
    if (fallback && fallback.proxies[0] !== "DIRECT") {
      throw new Error("漏网之鱼 does not prefer DIRECT");
    }
  }

  // Injected rules must sit at the head in declared order ...
  if (config.rules.length < retainedRules.length ||
      !retainedRules.every((rule, index) => config.rules[index] === rule)) {
    throw new Error("custom rule priority is invalid");
  }
  // ... and must never reference a policy target this config does not define,
  // otherwise mihomo refuses to load the whole subscription.
  const available = new Set([
    ...(Array.isArray(config["proxy-groups"]) ? config["proxy-groups"] : [])
      .map((group) => group && group.name)
      .filter(Boolean),
    ...(Array.isArray(config.proxies) ? config.proxies : [])
      .map((proxy) => proxy && proxy.name)
      .filter(Boolean),
    "DIRECT",
    "REJECT",
    "REJECT-DROP",
    "PASS",
    "COMPATIBLE",
  ]);
  for (const rule of retainedRules) {
    const target = ruleTarget(rule);
    if (target && !available.has(target)) {
      throw new Error(`injected rule references unknown policy target ${target}: ${rule}`);
    }
  }
}

function main(config) {
  const original = config;
  const warnings = [];
  try {
    if (!config || typeof config !== "object") throw new Error("invalid subscription config");
    const next = JSON.parse(JSON.stringify(config));
    delete next.__flclashRules;
    fixProviderPaths(next);
    const mode = configureGroups(next, warnings);
    const retained = configureRules(next, warnings);
    validateResult(next, mode, retained);
    // Visible application marker: check the subscription preview for
    // __flclashRules.applied to distinguish "override applied" (possibly
    // degraded - read warnings) from "override crashed and returned the
    // original config". rules tells how many custom rules were injected.
    next.__flclashRules = {
      applied: true,
      version: SCRIPT_VERSION,
      mode,
      rules: retained.length,
      warnings,
    };
    return next;
  } catch (error) {
    if (typeof console !== "undefined" && typeof console.error === "function") {
      const detail = error && error.stack ? error.stack : `${error && error.message}`;
      console.error(`[FlClash rules] extension skipped: ${detail}`);
    }
    return original;
  }
}
